<script lang="ts">import { onMount } from 'svelte'; import { client,ApiError,type SyncRun } from '$lib/api'; import { relativeTime } from '$lib/format'; import { currentUser } from '$lib/stores'; let runs=$state<SyncRun[]>([]); let error=$state(''); let busy=$state(false); async function load(){try{runs=await client.runs()}catch(e){error=e instanceof Error?e.message:'Sync history unavailable'}} onMount(load); async function trigger(){if(!confirm('Start a full guild sync?'))return;busy=true;try{await client.sync();await load()}catch(e){error=e instanceof ApiError?e.message:'Sync could not start'}finally{busy=false}}</script>
<h1>Keeper Controls</h1><section class="controls"><h2>Guild expedition sync</h2>{#if $currentUser?.appRole==='admin'}<button class="gold" disabled={busy} onclick={trigger}>{busy?'Dispatching…':'Trigger full sync'}</button>{:else}<span title="Only Guild Masters can trigger a full sync">Trigger restricted to Guild Master</span>{/if}<p>Scheduled runs keep the ledger fresh nightly at 03:00 UTC.</p></section>{#if error}<p class="error">{error}</p>{/if}<section><h2>Sync run history</h2><table><thead><tr><th>Started</th><th>Trigger</th><th>Status</th><th>Updated</th></tr></thead><tbody>{#each runs as run}<tr><td>{relativeTime(run.startedAt)}</td><td>{run.trigger}</td><td><span class="chip">{run.status}</span></td><td>{run.updated}</td></tr>{:else}<tr><td colspan="4">No sync runs recorded.</td></tr>{/each}</tbody></table></section><aside class="guidance"><h2>Battle.net credentials</h2><p>Set client credentials before your first sync. <a href="/docs/blizzard-setup.md">Read the keeper's setup guide</a>.</p></aside>
